export async function GET(request: Request) {
  let context: Awaited<ReturnType<typeof requireWorkspace>>;
  try { context = await requireWorkspace(); } catch { return NextResponse.json({ error: "Workspace unavailable" }, { status: 401 }); }
  const params = new URL(request.url).searchParams;
  const key = `moneo-conversation-${context.workspace.id}`;
  const headers = { "Cache-Control": "no-store" };
  try {
    // The sidebar pages and searches threads without reloading the open conversation.
    if (params.get("view") === "threads")
      return NextResponse.json(await loadThreads(context.supabase, context.workspace.id, params.get("threadsBefore") ?? undefined, params.get("q") ?? undefined), { headers });
    const requested = params.get("conversation") ?? (await cookies()).get(key)?.value;
    return NextResponse.json({ ...await loadConversationHistory(context.supabase, context.workspace.id, requested, params.get("threadsBefore") ?? undefined, params.get("messagesBefore") ?? undefined), selectionKey: key }, { headers });
  } catch (cause) {
    return NextResponse.json({ selectionKey: key, error: cause instanceof Error ? cause.message : "Could not load conversation" }, { status: 400 });
  }
}
